# Handled cleanly via generics.RetrieveUpdateDestroyAPIView:
class TaskDetailView(generics.RetrieveUpdateDestroyAPIView):
    serializer_class = TaskSerializer
    permission_classes = [permissions.IsAuthenticated]

    def get_queryset(self):
        return Task.objects.filter(owner=self.request.user)

class TaskStatusUpdateView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def patch(self, request, pk):
        task = get_object_or_404(Task, pk=pk, owner=request.user)
        if 'is_completed' not in request.data or not isinstance(request.data['is_completed'], bool):
            return Response({'is_completed': ['A valid boolean is required.']}, status=status.HTTP_400_BAD_REQUEST)
        task.is_completed = request.data['is_completed']
        task.save(update_fields=['is_completed', 'updated_at'])
        serializer = TaskSerializer(task)
        return Response(serializer.data, status=status.HTTP_200_OK)
